              "**Common signs include visibly receding gums, teeth that appear longer than they used to, exposed tooth roots, and sensitivity to hot, cold, or sweet foods. Even mild recession is worth evaluating, since it tends to progress over time. During your consultation, we’ll measure your gum levels and let you know whether grafting is necessary — or whether monitoring is enough for now.**"
